(function(){'use strict';
const $=id=>document.getElementById(id),M=SettingsSearchModel,aliases={rrr:'возврат ресурсов ррр', 'hideout-return':'возврат убежища будка гильдия','craft-place':'место производства город станка убежище будка','use-focus':'включить использовать фокус','focus-budget':'бюджет фокус очки','quantity':'объем количество партия сколько получить','volume-mode':'режим объема количество партия по фокусу','quantity-mode':'режим объема количество автоматически вручную','capacity':'грузоподъемность вес груз свободный','sale-price':'цена продажи доход','buy-price':'цена покупки закупка','craft-city':'город производства станок','sell-city':'город продажи маршрут','eff':'эффективность фокус мастерства специализация','station':'тариф плата станок питание','setup':'комиссия выставление постановка ордера','tax':'налог налоги продажа','buffer':'запас резерв закупка материалы','transport':'доставка перевозка расходы','premium':'премиум подписка','theme':'тема оформление цвет','view-density':'плотность компактность интерфейс','view-sticky':'закрепление результат прокрутка','view-hints':'пояснения подсказки шаги'};
function scope(){const mode=Workspace.activeMode();return $(['food','potions','gear','refine','bags'].includes(mode)?'craft-content':mode+'-content');}
function label(node){const host=node.closest('label');if(!host)return node.getAttribute('aria-label')||'';const read=n=>n.nodeType===3?n.textContent:['INPUT','SELECT','TEXTAREA','BUTTON','SMALL'].includes(n.nodeName)?'':[...n.childNodes].map(read).join(' ');return read(host).replace(/\s+/g,' ').trim();}
function usable(node,host){if(!node||!host?.contains(node)||node.disabled||node.type==='hidden'||node.type==='search'||node.closest('dialog,.block-summary'))return false;for(let p=node;p&&p!==host.parentElement;p=p.parentElement)if(p.hidden)return false;return Boolean(label(node));}
function block(node){const host=node.closest('[data-screen-block],.character-group,.step-card,.panel'),heading=host?.querySelector(':scope>summary .advanced-title')||host?.querySelector(':scope>summary,h2,h3'),group=node.closest('.advanced-group')?.querySelector('h3');return [heading?.textContent||'Параметры расчёта',group?.textContent].filter(Boolean).map(text=>text.replace(/^\d+\.\s*/,'').replace(/\s+/g,' ').trim()).join(' / ');}
function inventory(){const host=scope(),mode=Workspace.activeMode(),ticket=Workspace.ticket(),sets=host&&!host.hidden&&ticket.tabId?[[host,false]]:[];sets.push([document.querySelector('.interface-options'),true]);const records=[];for(const [area,view]of sets)for(const node of area.querySelectorAll('input[id],select[id],textarea[id]')){if(!usable(node,area))continue;const key=Object.keys(aliases).find(k=>node.id===k||node.id.endsWith('-'+k));records.push({key:'setting:'+node.id,source:'settings',target:{type:'setting',id:node.id,mode,ticket,view},label:label(node),hint:view?'Настройки вида':block(node),aliases:[aliases[key]||'',node.id].join(' ')});}return records;}
function resolve(target){const node=$(target.id),area=target.view?document.querySelector('.interface-options'):scope(),available=target.mode===Workspace.activeMode()&&Workspace.accept(target.ticket)&&usable(node,area);return {available,mode:target.mode,label:node?label(node):'Параметр недоступен',reason:available?'':'Расчёт или доступность параметра изменились. Повторите поиск.',node};}
function value(node){return node.type==='checkbox'?(node.checked?'Включено':'Выключено'):node.tagName==='SELECT'?node.selectedOptions[0]?.textContent||'':node.value||'Не заполнено';}
let highlighted=null,highlightTimer;
function focus(node,view){const control=window.ItemPicker?.attachment(node.id)?.trigger||node;if(!control.checkVisibility())return false;control.focus({preventScroll:true});control.scrollIntoView({block:view?'nearest':'center',behavior:'instant'});highlighted?.classList.remove('settings-search-highlight');clearTimeout(highlightTimer);highlighted=node.closest('label')||node;highlighted.classList.add('settings-search-highlight');highlightTimer=setTimeout(()=>{highlighted?.classList.remove('settings-search-highlight');highlighted=null;},2400);return true;}
// Open the menu after the result click has passed the existing outside-click handlers.
function go(target){const resolved=resolve(target);if(!resolved.available)return false;const node=resolved.node;if(target.view){window.scrollTo({top:0,behavior:'instant'});setTimeout(()=>{if(!resolve(target).available)return;document.querySelector('.interface-menu').open=true;CompactHeaderUI.open();focus(node,true);},0);return true;}CompactHeaderUI.close();QuickNavigation.reveal(node);BlockSummaries.sync();return focus(node,false);}
const switches=document.createElement('div');switches.className='settings-search-scopes';switches.setAttribute('role','group');switches.setAttribute('aria-label','Область поиска');for(const [key,text]of [['all','Всё'],['settings','Настройки']]){const button=document.createElement('button');button.type='button';button.className='button';button.dataset.searchScope=key;button.textContent=text;button.setAttribute('aria-pressed',String(key==='all'));button.onclick=()=>{CommandSearch.setScope(key);$('command-search-input').focus();};switches.append(button);}$('command-search-input').before(switches);$('command-search-input').placeholder='Предмет, раздел, свой крафт или настройка';
const launch=document.createElement('button');launch.type='button';launch.className='button';launch.id='settings-search-open';launch.textContent='Найти параметр текущего раздела';launch.onclick=()=>{CompactHeaderUI.close();$('command-search-open').focus({preventScroll:true});CommandSearch.openSettings();};document.querySelector('.interface-options h3').after(launch);
window.SettingsSearch={search:query=>M.search(inventory(),query),resolve,go,value,inventory};
})();
